)

$ok = 0; $fail = 0
foreach ($img in $images) {
  Write-Host "Downloading $($img.dest)..."
  try {
    Invoke-WebRequest -Uri $img.url -OutFile $img.dest -UseBasicParsing -TimeoutSec 15
    $ok++
    Write-Host "  OK"
  } catch {
    $fail++
    Write-Host "  FAILED: $_"
  }
}
Write-Host "`nDone. OK=$ok FAILED=$fail"
